<?php require 'helpers.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT e.*,c.name AS club_name,c.id AS club_id FROM events e JOIN clubs c ON c.id=e.club_id WHERE e.id=?');$q->execute([$id]);$event=$q->fetch();if(!$event){http_response_code(404);exit('Event not found.');}$pageTitle=$event['title'];
if($_SERVER['REQUEST_METHOD']==='POST'){require_login();if(current_user()['role']!=='student'){flash('Only student accounts can register for events.','error');redirect('event.php?id='.$id);}if(strtotime($event['event_date'])<=time()){flash('This event has already started or ended, so registration is closed.','error');redirect('event.php?id='.$id);}try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT capacity FROM events WHERE id=? FOR UPDATE');$q->execute([$id]);$capacity=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM registrations WHERE event_id=?');$q->execute([$id]);$count=(int)$q->fetchColumn();if($count >= $capacity){$pdo->rollBack();flash('Sorry, this event is full.','error');}else{$q=$pdo->prepare('INSERT IGNORE INTO registrations(user_id,event_id) VALUES(?,?)');$q->execute([current_user()['id'],$id]);$pdo->commit();flash($q->rowCount()?'Your spot is reserved!':'You are already registered.');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Could not complete registration. Please try again.','error');}redirect('event.php?id='.$id);}
require 'header.php';$q=$pdo->prepare('SELECT COUNT(*) FROM registrations WHERE event_id=?');$q->execute([$id]);$count=(int)$q->fetchColumn();$registered=false;if(is_logged_in()){$q=$pdo->prepare('SELECT id FROM registrations WHERE event_id=? AND user_id=?');$q->execute([$id,current_user()['id']]);$registered=(bool)$q->fetch();} $isPast=strtotime($event['event_date'])<=time(); ?>
<section class="event-detail"><span class="tag"><?=e($event['club_name'])?></span><h1><?=e($event['title'])?></h1><p class="lead"><?=e($event['description'])?></p><div class="detail-grid"><div><span class="eyebrow">DATE & TIME</span><strong><?=date('l, F j, Y',strtotime($event['event_date']))?></strong><span><?=date('g:i A',strtotime($event['event_date']))?></span></div><div><span class="eyebrow">LOCATION</span><strong><?=e($event['venue'])?></strong></div><div><span class="eyebrow">AVAILABILITY</span><strong><?=$count?> / <?= (int)$event['capacity']?> registered</strong><span><?=max(0,(int)$event['capacity']-$count)?> seats left</span></div></div><?php if(is_logged_in() && current_user()['role']==='student'): ?><form method="post"><?php csrf_field(); ?><button class="btn primary" <?=($registered || $isPast || $count >= (int)$event['capacity'])?'disabled':''?>><?=$registered?'You are registered':($isPast?'Registration closed':($count >= (int)$event['capacity']?'Event is full':'Register with one click'))?></button></form><?php elseif(!is_logged_in()): ?><a class="btn primary" href="login.php">Log in to register</a><?php endif; ?><div style="margin-top: 25px;"><a class="text-link" href="club.php?id=<?=$event['club_id']?>">← Back to club</a></div></section>
<?php require 'footer.php'; ?>
